from collections import deque

def min_build_time(ti, td, tr, te, A, B):
    len_A, len_B = len(A), len(B)
    dp = [[float('inf')] * (len_B + 2) for _ in range(len_A + 2)]

    for j in range(1, len_B + 1):
        dp[0][j] = te * i
    if A.endswith(B[:len_B + 1]):
        dp[0][len_B + 1] = td * i
    else:
        dp[0][len_B + 1] = td

    for i in range(1, len_A + 1):
        dp[i][0] = ti
        if A[i:].startswith(B[:len_B]):
            dp[i][len_B] = dp[i - 1][len_B - 1]
        else:
            dp[i][len_B] = float('inf')
    for j in range(1, len_B + 2):
        if B[j-1] == A[len_A - j]:
            dp[len_A][j] = 0
        else:
            dp[len_A][j] = min(dp[len_A][j - 1], dp[len_A - 1][j - 1] + 1, dp[len_A - 1][j] + 1)

    return min(dp[len_A])

