import sys

def find_winner(segment_l, segment_r, terminal_l, terminal_r, alice_moves):
    # Calculate the number of moves Alice can make
    alice_moves += max(segment_l - terminal_l + 1, segment_r - terminal_r + 1)
    # Check if Bob wins immediately
    if segment_l > terminal_r or segment_r < terminal_l:
        return alice_moves
    # If Bob wins immediately, return the count
    if segment_l == terminal_l and segment_r == terminal_r or segment_l == terminal_r and segment_r == terminal_l:
        return 0
    # Continue the game
    if segment_l >= terminal_l:
        return find_winner(segment_l, segment_r, terminal_l, terminal_r - (segment_r - terminal_r), alice_moves)
    else:
        return find_winner(segment_l, segment_r, terminal_l + 1, terminal_r, 0)

def game_winner(initial_segments, terminal_segments):
    alice_moves = 0
    results = [None] * len(initial_segments)
    for i in range(len(initial_segments)):
        results[i] = find_winner(initial_segments[i][0], initial_segments[i][1], terminal_segments[0][0], terminal_segments[0][1], alice_moves % 2)
    return results

