from collections import defaultdict

def max_profit(N, M, A, B, edges):
    scores = [0] * N

    # Build adjacency list
    graph = defaultdict(list)
    for u, v in edges:
        graph[u-1].append(v-1)
        graph[v-1].append(u-1)

    for i in range(N):
        scores[i] = abs(B[i])

    # Build contribution graph for max flow
    contribution_graph = defaultdict(list)
    for u, v in edges:
        for neighbor in graph[u-1]:
            if neighbor != v-1:
                contribution_graph[(u-1, v-1)].append((u-1, v-1))
                contribution_graph[(v-1, u-1)].append((v-1, u-1))

    # Build residual graph for max flow
    residual = [[{'cost': 0, 'flow': 0} for _ in range(N)] for _ in range(N)]

    # Max flow algorithm
    max_flow = 0
    flow = 0
    while flow < N:
        path, components = bfs(contribution_graph, residual, scores, max_flow)
        if not path:
            break
        for u, v in components:
            residual[u][v]['flow'] -= 1
            residual[v][u]['flow'] += 1
        path.pop(0)
        for u, v in edges:
            if (u-1, v-1) in path:
                residual[u][v]['cost'] += scores[v-1] - scores[u-1]
                residual[v][u]['cost'] -= scores[v-1] - scores[u-1]
        max_flow += path[-1][1]

    # Calculate profit
    profit = max(scores)
    for i in range(N):
        if i != path[-1][0]:
            profit = max(profit, B[i] - residual[path[-1][0]][i]['cost'])

    return profit

def bfs(graph, residual, scores, max_flow):
    queue = [(0, -1)]
    visited = set()
    while queue:
        cost, node = queue.pop(0)
        if node != -1 and cost <= max_flow:
            for neighbor, capacity, flow_cost in graph[node]:
                if capacity - flow_cost > 0 and (neighbor, node) not in visited:
                    visited.add((neighbor, node))
                    queue.append((cost + flow_cost, neighbor))
    for neighbor, node in visited:
        residual[node][neighbor]['cost'] = scores[neighbor]
    return neighbors, visited

def solve():
    N, M = map(int, input().split())
    A = list(map(int, input().split()))
    B = list(map(int, input().split()))
    edges = []
    for _ in range(M):
        u, v = map(int, input().split())
        edges.append((u-1, v-1))

    print(max_profit(N, M, A, B, edges))

if __name__ == "__main__":
    solve()
