# Fast computation of (2^k) % MOD with binary exponentiation
def powToMod(m, k, MOD):
    return pow(m, k, MOD)

# Fast computation of (2^(2*k)) % MOD with fast double exponentiation
def powToMod2(m, k, MOD):
    return powToMod(powToMod(m, k, MOD), 2, MOD)

# Function to compute a^n % MOD using a fast exponentiation method
def modExp(x, n, p):
  r = 1
  k = p
  y = x
  while k > 0:
    if k & 1: 
      r = r * y
      r %= p
    y = y * y
    k = k >> 1
  return r

# Function to compute the sum of F^k % MOD for k from 0 to n-1
def sumMod(n, MOD):
  return modExp(3, n, MOD)

# Function to compute the sum of F^k % MOD for k from 0 to n-1 using BIT
def BITSum(n, MOD):
  return sum([sumMod(k, MOD) for k in range(N)]) % MOD

# Function to compute the sum of F^k % MOD for k from 0 to n-1 using C (prefix odd bits sum)
def XORSum(n, MOD):
  sumF = 0
  i = 0
  for m in range(n):
    sumF ^= sumMod(i, MOD)
    i += 2
    sumF %= MOD
  return sumF % MOD

