from collections import deque

def min_time_to_convert(A, B):
    queue = deque()
    for letter in A:
        queue.append(letter)
    for letter in B:
        if letter != queue[0]:
            exchange_queue = deque(queue)
            for _ in range(2):
                queue.append(queue.popleft())
            for _ in range(len(queue) // 2):
                queue.append(queue.popleft())
            for _ in range(len(queue) // 2):
                queue.append(queue.popleft())
            queue.extend(exchange_queue)
        else:
            queue.append(letter)
    return len(queue)

