from collections import deque

def build_graph(sequence_a, sequence_b):
    n = len(sequence_a) + 1
    graph = [[] for _ in range(n)]
    tmp = 0

    for i in range(n):
        for j in range(n):
            if i != j and sequence_a[i] == sequence_b[j]:
                graph[i].append((j, tmp + 1))
                graph[j].append((i, tmp + 1))
                tmp += 1

    return graph

def dijkstra(graph, start):
    n = len(graph)
    distance = [float('inf')] * n
    distance[start] = 0
    queue = deque([(start, 0)])

    while queue:
        u, dist = queue.popleft()
        for v, w in graph[u]:
            if distance[v] > distance[u] + w:
                distance[v] = distance[u] + w
                queue.append((v, distance[v]))

    return distance

def minimum_time(sequence_a, sequence_b, ti, td, tr, te):
    n = len(sequence_a)
    time_required = te + td

    for i in range(n - 1):
        time_required += te

    delta_b = 0
    dijkstra_e = dijkstra(graph, 0)
    for i in range(n):
        for _, d in sorted(filter(lambda x: x[1] == 0 and (d >= delta_b and d <= min(dijkstra_e)), dijkstra_e)):
            if d < delta_b:
                delta_b = d

            time_required += td

    delta_a = 0
    for i in range(n - 1):
        time_required += td

    dijkstra_e = dijkstra(graph, n - 1)
    for i in range(n):
        for _, d in sorted(filter(lambda x: x[1] == 0 and (d >= delta_a and d <= min(dijkstra_e)), dijkstra_e)):
            if d < delta_a:
                delta_a = d

            time_required += tr

    delta_a = max(0, tr - td - delta_a)
    delta_b = 2 * delta_b - max(delta_b, td - tr + te - delta_a)

    return time_required + max(delta_a + delta_b, 0)

def main():
    ti, td, tr, te = map(int, input().split())
    sequence_a = input().strip()
    sequence_b = input().strip()
    print(minimum_time(sequence_a, sequence_b, ti, td, tr, te))

if __name__ == "__main__":
