def process_jars(jars, capacity=5):
    n = len(jars)
    initial_jars = [0] * n
    reverse_initial_jars = {j + 1: i for i, j in enumerate(jars)}
    current_position = deque([0 for _ in range(n)])

    def rearrange():
        nonlocal jars, current_position
        for j in current_position:
            if j < n - j:
                jars[max(j, j + 1)], jars[min(j, n - j - 1)] = \
                    jars[min(j, n - j - 1)], jars[max(j, j + 1)]
                current_position[current_position.index(j)] = j + 1
            else:
                jars[j - j], jars[j] = jars[j], jars[j - j]
                current_position[current_position.index(j - j)] = j - j
                current_position.append(j - 1)

    steps = 0
    while 1:
        current_position.clear()
        for i, jar in enumerate(jars):
            current_position.appendleft(0)
            current_position.appendleft(jar)
        current_position.appendleft(0)
        current_position.appendleft(0)

        if steps > 1 or len(jars) == 1 or len(jars) == n:
            break

        while current_position:
            rearrange()
            steps += 1

    return steps, sorted(initial_jars)

