from collections import defaultdict

def splitArmyByGroups(hp, m, n):
    groups = []
    for i in range(m):
        distance = max(hp) * n
        if distance >= n:
            groups.append([n] * n)
            break
        remaining = -(m * n)
        for j in range(n):
            remaining += -(distance % (m - 1)) + hp[j]
        groups.append([int(distance / (m - 1) + 1)] * n)
    return groups

def minStepsToDestroyEnemies(groups, armies):
    n = len(groups)
    m = len(armies)
    steps = min(armies[i] / group[i] for group in groups for i in range(m))
    all_steps = steps * n
    for group in groups:
        all_steps += armies[n - n + sum(group) - 1//m]
    return all_steps

def findBestSplitAndSteps(hp, m, n):
    armies = list(enumerate(hp, 1))
    groups = splitArmyByGroups(hp, m, n)
    steps = minStepsToDestroyEnemies(groups, armies)
    current = steps
    current_groups = defaultdict(int)
    for s, step in steps:
        for group in groups:
            if group[current] != 0:
                if current_groups[armies[group[current] - 1]][0] > n - sum(group):
                    current = group[current] - current_groups[armies[group[current] - 1]][0]
                    step[current] += (n - sum(group)) // m
                else:
                    break
        current_groups[armies[s - 1]] = (s, step[s-1])

