import sys

def min_rearrangements(nums):
    n = len(nums)
    min_ops = sys.maxsize
    operations = []

    def backtrack(start, taken, taken_index, nums, ops, ops_count):
        nonlocal min_ops
        if ops_count >= min_ops:
            return
        if start == n:
            min_ops = min(min_ops, ops_count)
            return
        if ops_count > min_ops:
            ops.append((start, taken))
            return
        chosen = nums[start - 1]
        for i in range(start, n):
            if nums[i] > chosen:
                nums[start - 1], nums[i] = nums[i], nums[start - 1]
                backtrack(start + 1, taken + [i], taken_index - (len(nums[start:]) - i), nums, ops, ops_count + 1)
                nums[start - 1], nums[i] = nums[i], nums[start - 1]

    backtrack(1, [], n, nums, [], 0)

    for i, taken in operations:
        print(f"{len(taken)}", end=" ")
        for t in taken:
            print(f"{t + 1} ", end="")
