def game_winner(n, m, initial, terminal):
    initial.sort(key=lambda x: x[1], reverse=True)
    terminal.sort()
    jumps = []
    for r in terminal:
        heappush(jumps, r)
    ans = [-1] * n

    for l, r in initial:
        while jumps and jumps[0] <= l:
            heappop(jumps)
        if not jumps:
            ans[r-1] = 0
        elif jumps[0] < l:
            jumps = config(changes=int(jumps[0]-l), excl=r)
        elif jumps[0] >= l:
            ans[r-1] = 1
        if ans[l-1] != -1:
            break
    return ans

def config(changes, excl):
    while changes > excl - 1:
        heappush(changes, heappop(changes) - 1)
    while excl > 0:
        heappush(changes, 0)
