        self.universities = defaultdict(list)
        self.military_offices = defaultdict(list)
        self.dormitories = []
        self.dormitorial_usage = defaultdict(int)
        self.all_used_dormitories = set()

    def merge_universities(self, university1, university2):
        self.universities[university1] = self.universities.get(university1, [])
        self.universities[university2] = self.universities.get(university2, [])
        self.universities[university1].extend(self.universities[university2])
        self.universities.pop(university2)

    def merge_military_offices(self, military_office1, military_office2):
        self.military_offices[military_office1] = self.military_offices.get(military_office1, [])
        self.military_offices[military_office2] = self.military_offices.get(military_office2, [])
        self.military_offices[military_office1].extend(self.military_offices[military_office2])
        self.military_offices.pop(military_office2)

    def assign_dormitory_to_university(self, dormitory, university):
        if university in self.universities and dormitory not in self.all_used_dormitories:
            self.universities[university].append(dormitory)
            for office in self.universities[university]:
                self.dormitorial_usage[office] += 1
            self.all_used_dormitories.add(dormitory)

    def move_students(self, university, dormitory):
        self.dormitorial_usage[university] += dormitory

    def conduct_raids(self, military_office):
        for office in self.military_offices[military_office]:
            for dormitory in self.all_used_dormitories:
                self.all_used_dormitories.remove(dormitory)
        self.all_used_dormitories |= set(self.military_offices[military_office])

    def count_people_in_dormitory(self, dormitory):
        return self.dormitorial_usage[self.dormitories.index(dormitory)]

    def process_changes(self, changes):
        for change in changes:
            if 'A' in change:
                university, dormitory = int(change.split()[1]), int(change.split()[2])
                self.assign_dormitory_to_university(dormitory, university)
            if 'M' in change:
                military_office, dormitory = int(change.split()[1]), int(change.split()[2])
                self.merge_military_offices(military_office, dormitory)
            if 'Z' in change:
                self.conduct_raids(int(change.split()[1]))
            if 'Q' in change:
                _, dormitory = int(change.split()[1]), int(change.split()[2])
                yield self.count_people_in_dormitory(dormitory)

