def min_steps_to_destroy_enemies(n: int, m: int, health_points: List[int]) -> int:
    total_hp = sum(health_points)
    if total_hp == n:
        return 1
    if total_hp % n == 0:
        return 1

    m_plus_1 = min(total_hp // n, m)
    if m_plus_1 > m:
        return -1
    steps = 1
    remaining_hp = total_hp % n

    while remaining_hp > 0:
        half_hp = remaining_hp // 2
        if half_hp == 0:
            half_hp = 1
        half_step = (n // m) * half_hp + (n % m) * remaining_hp
        if half_step > n:
            return -1
        steps += 1
        remaining_hp = (n // m) * half_hp + (n % m) * half_hp
        if remaining_hp == 0:
            return steps

    return steps

