from functools import lru_cache
from itertools import combinations

def calculate_depth_helper(s, prefix):
    @lru_cache(maxsize=None)
    def depth_helper(i, stack):
        if i == len(s):
            return 0
        if s[i] == '(':
            return depth_helper(i + 1, stack + [(i, 1)])
        elif s[i] == ')':
            if stack and stack[-1][0] == i - 1:
                stack.pop()
                return depth_helper(i + 1, stack)
            else:
                return depth_helper(i + 1, stack + [(i, -1)])
        else:
            return max(depth_helper(i + j, (k, 1 if j else -1) + v) for j, v in enumerate(prefix[(i, 0)]) if i - j <= len(s))

    return max(depth_helper(i, [(i // 2, 1) if i % 2 == 1 else (i // 2, -1)]) for i in range(0, len(s) + 1, 2))

def solve(arr):
    magical_brackets = ['(', ')']
    special_brackets = ['(?), ?', '(?)']

    magical_bracket_depths = {b: calculate_depth_helper(arr, b) for b in magical_brackets}
    special_bracket_depths = {s: calculate_depth_helper(arr, s) for s in special_brackets}
    magical_bracket_depths[f'?{len(arr) // 2 - 1}'] = 1
    special_bracket_depths[f'?{len(arr) // 2 - 1}'] = 1

    return (sum(magic_bracket_depths.get(b, 0) for b in magical_brackets) +
            sum(special_bracket_depths.get(b, 0) for b in special_brackets) +
            special_bracket_depths.get('?{len(arr) // 2}', 0)) % 998244353

