MOD = 998244353

def calculate_depth(a):
    n = len(a)
    dp = [0] * n
    stack = [-1]
    for i in range(n):
        if a[i] == '(':
            stack.append(i)
        else:
            dp[i] = (2 * dp[stack.pop()] + 1) % MOD
    return max(dp)

def solve(a):
    if '?' not in a:
        return calculate_depth(a)

    n = len(a)
    dp = [0] * n
    stack = [-1]

    # Count '?' positions
    q = 0
    for i in range(n):
        if a[i] == '?':
            q += 1

    if q % 2 == 1:
        q = (q // 2) + 1
    else:
        q //= 2

    dp[0] = 1

    for i in range(1, n):
        if a[i] == '?':
            dp[i] = dp[stack.pop()] * 2 % MOD
        else:
            dp[i] = dp[stack.pop()]
        dp[i] += 1
        dp[i] %= MOD

        if a[i] == '(':
            stack.append(i)

    return (dp[-1] + 1) * q % MOD

