from functools import cache

def min_time_to_convert(A, B):
    A = list(A)
    B = list(B)

    @cache
    def dp(j, i, k):
        nonlocal A, B
        if i == len(B):
            return 0
        if j == len(A):
            return len(B) - i

        time = inf
        if k == 0:
            time = dp(j+1, i, 0) + A[j].islower()  # Insert 'a' if a lowercase letter
            time = min(time, dp(j, i+1, 0) + (B[i].islower() - A[j].islower()) * 2)  # Insert 'a' and delete current a
        if k == 1:
            time = dp(j, i+1, 1) + (1 if A[j] == B[i] else 8)  # Insert or swap if it matches
        if k == 2:
            time = dp(j+1, i, 2) + min(A[j].islower() - B[i].islower(), B[i].islower() - A[j].islower()) * 2
            time = min(time, dp(j, i+1, 2) + (A[j] == B[i]))
        if k == 3:
            time = dp(j+1, i, 3) + B[i] < A[j] and B[i].islower()
            time = min(time, dp(j, i+1, 3) + (B[i] > A[j]).and_(A[j].islower() != B[i].islower()))

        return time

    return dp(0, 0, 0)

